algorithms.pseudocode:
function VERIFY_AVERAGING(C, q, n, r):
    space <- all q^n strings of length n over {0..q-1}
    total <- 0
    for z in space:
        for c in C:
            if hamming(c, z) <= r: total <- total + 1
    ball <- |{ x in space : hamming(x, 0^n) <= r }|
    return (total == |C| * ball)
